#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXV = 10005;
const int MAXE = 2000000 + 10;
const int INF = 2000000000;
const int SRC = MAXV - 2;
const int SNK = MAXV - 1;

int to[MAXE], cap[MAXE], ecost[MAXE], ecnt = 1;
vector<int> adj[MAXV];
ll dis[MAXV];
bool used[MAXV];
queue<int> q;

inline void add(int u, int v, int f, int w) {
    ++ecnt;
    to[ecnt] = v; cap[ecnt] = f; ecost[ecnt] = w;
    adj[u].push_back(ecnt);
    ++ecnt;
    to[ecnt] = u; cap[ecnt] = 0; ecost[ecnt] = -w;
    adj[v].push_back(ecnt);
}

inline bool spfa() {
    memset(used, 0, sizeof(used));
    memset(dis, 0x3f, sizeof(dis));
    q.push(SNK); dis[SNK] = 0; used[SNK] = 1;
    while (!q.empty()) {
        int x = q.front(); q.pop();
        used[x] = 0;
        for (int idx = (int)adj[x].size() - 1; idx >= 0; --idx) {
            int e = adj[x][idx];
            int y = to[e];
            if (cap[e ^ 1] && dis[y] > dis[x] + ecost[e ^ 1]) {
                dis[y] = dis[x] + ecost[e ^ 1];
                if (!used[y]) { q.push(y); used[y] = 1; }
            }
        }
    }
    return dis[SRC] < 1e18;
}

inline int dfs(int x, int lim, ll &total) {
    int flow = 0;
    used[x] = 1;
    if (x == SNK) return lim;
    for (int idx = (int)adj[x].size() - 1; idx >= 0; --idx) {
        int e = adj[x][idx];
        int y = to[e];
        if (!cap[e] || used[y]) continue;
        if (dis[x] != dis[y] + ecost[e]) continue;
        int t = dfs(y, min(cap[e], lim - flow), total);
        cap[e] -= t;
        cap[e ^ 1] += t;
        flow += t;
        total += t * ecost[e];
        if (flow == lim) return lim;
    }
    return flow;
}

inline ll minCostFlow() {
    int totalFlow = 0;
    ll totalCost = 0;
    while (spfa()) {
        do {
            memset(used, 0, sizeof(used));
            totalFlow += dfs(SRC, INF, totalCost);
        } while (used[SNK]);
    }
    return totalCost;
}

int main() {
    int n, m, k, c, d, lim = 101;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) { int x; cin >> x; --x; add(SRC, x, 1, 0); }
    for (int i = 0; i < lim; i++) add(i * n, SNK, k, c * i);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < lim - 1; j++)
            add(i + j * n, i + (j + 1) * n, k, 0);
    while (m--) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < lim - 1; i++)
            for (int j = k - 1; j >= 0; j--) {
                add(x + i * n, y + (i + 1) * n, 1, d * (2 * j + 1));
                add(y + i * n, x + (i + 1) * n, 1, d * (2 * j + 1));
            }
    }
    cout << minCostFlow();
    return 0;
}
